OpNoviceDetectorConstruction::OpNoviceDetectorConstruction()
 : G4VUserDetectorConstruction()
{
  fExpHall = 5*m;

  SteelZ = 21*cm;
  WallThick = 5*mm;
  SctZ = SteelZ - WallThick*2;

  Diam_WOM_Out = 60*mm;
  Thickness_WOM = 3*mm;
  Diam_WOM_In = Diam_WOM_Out - 2*Thickness_WOM;
  Thickness_Air = 2*mm;
  Diam_Out_In = Diam_WOM_Out + 2*Thickness_Air;
  Thickness_Vessel = 3*mm;
  Diam_Out_Out = Diam_Out_In + 2*Thickness_Vessel;
  Diam_In_Out = Diam_WOM_In - 2*Thickness_Air;
  Diam_In_In = Diam_In_Out - 2*Thickness_Vessel;
  Diam_Steel_Add = 120*mm;
  Diam_Hat = 120*mm;
  Thickness_Disk = 3*mm;
  Thickness_Ring = 3*mm;
  Thickness_Hat = 5*mm;
  Thickness_WLS = 0.02*mm;
  Thickness_Gap = 1*mm;
  Thickness_Steel_Add_Top = 16.19*mm - Thickness_Hat;
  Thickness_Steel_Add_Bot = 12*mm - Thickness_Hat;
  Length_Out = 200*mm;
  Length_WOM = 205*mm;
  Length_In = 195*mm;
  Length_sipm_box = 15*cm;

  n_sipm = 40;
  sipmSizeSens = 3*mm;
  sipmSize = sipmSizeSens + 0.4*mm;
  sipmBaseThickness = 1.*mm;
  sipmWindowThickness =  0.15*mm;
  sipmSensThickness = 0.149*mm;
  sipmSensThicknessTop = 0.001*mm;

  ytl = 632;
  ytr = 618;
  ybl = 610;
  ybr = 638;
  double ytm = (ytl+ytr)/2;
  double ybm = (ybl+ybr)/2;
  double height = ytm+ybm;
  WOM_coord_vec = {{0*mm, 312.5*mm}, {0*mm, -312.5*mm}};
}

